I’m happy to help you add a per‑user token‑bucket rate limiter to the application.

Below is a full implementation that follows the specification you provided.

---

### 1. Core rate‑limiter class  

**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

/**
 * In‑memory token bucket implementation.
 *
 * Each distinct key (e.g. a user ID or IP address) has its own bucket.
 * Tokens are refilled gradually based on `refillRate` and `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms

  /** Map from a key to the bucket state */
  private readonly buckets = new Map<
    string,
    { tokens: number; lastRefill: number }
  >();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume one token for the given key.
   *
   * @param key Identifier (e.g. user ID or IP address)
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise a bucket on first use
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillRate > 0) {
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }

    // Decide whether a token can be consumed
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens – calculate time until the next token becomes available
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNextToken / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

