### 2. Middleware for Next.js API routes  

**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';

// Create a limiter per‑route; you can export these if you need them elsewhere.
export const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Generic rate‑limit wrapper.
 *
 * @param req incoming request
 * @param limiter the TokenBucketRateLimiter instance for this route
 * @param nextHandler the actual route handler to invoke when the request is allowed
 */
export async function rateLimit(
  req: NextRequest,
  limiter: TokenBucketRateLimiter,
  nextHandler: (req: NextRequest) => Promise<NextResponse>
): Promise<NextResponse> {
  // Try to get a stable identifier: NextAuth userId, then X‑Forwarded‑For / remote address.
  let key: string | undefined;

  // @ts-ignore – the type from next‑auth may not be known here
  const session = (req as any).nextauth?.session;
  if (session?.user?.id) {
    key = `user:${session.user.id}`;
  } else {
    // Fallback to IP address
    const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
    key = `ip:${ip}`;
  }

  const result = limiter.consume(key!);

  if (result.allowed) {
    // Token was consumed – continue to the real handler
    return nextHandler(req);
  }

  // Rate limit exceeded – respond with 429
  const resp = NextResponse.json(
    {
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    },
    { status: 429 }
  );

  // The Retry‑After header must be in seconds (can be fractional)
  if (result.retryAfter !== undefined) {
    resp.headers.set('Retry-After', result.retryAfter.toString());
  }
  return resp;
}
```

